#!/bin/bash
# Deploy an update for ${PROJECT}: pull the source repositories (if they are git
# checkouts), upgrade the given modules, restart. Usage: sudo ${SERVICE}-update [module,module]
# Generated by baremetal/install.sh.
set -euo pipefail
MODS=${1:-base}
for r in ${GIT_REPOS}; do
  [ -d "$r/.git" ] || continue
  echo "== $r"; runuser -u "$(stat -c %U "$r")" -- git -C "$r" pull --ff-only
done
systemctl stop ${SERVICE}
runuser -u ${ODOO_USER} -- ${VENV}/bin/python ${ODOO_SRC}/odoo-bin -c ${CONF_FILE} -d ${DB_NAME} -u "$MODS" --stop-after-init --no-http
systemctl start ${SERVICE}
sleep 5; curl -fsS -o /dev/null -w "odoo answers %{http_code}\n" http://127.0.0.1:${HTTP_PORT}/web/login
